/// The gap the C compiler leaves between two neighbouring fields of a record, measured: the bytes
/// between the first one's end and the second one's start.
///
/// What this can and cannot catch, said once here: a gap is a difference between two offsets, so
/// these asserts are implied by the two `offset_of!` pins around them and cannot fail on their own.
/// What they do is state where the compiler's padding is, in numbers taken from the C compiler, so
/// that the padding is visible in the test instead of hiding behind a `size_of` that cannot see it —
/// and so that a record whose fields are reordered, widened or narrowed has to move a *measured*
/// number rather than keep a size it happens to match. (Injected: adding a `u16` field into the
/// picture record's two-byte gap left every test here green, because it changes neither the size nor
/// any offset. That is not a hole in this test, it is the point of `#[repr(C)]:` the fix for "this
/// record has a hole" is never to write the padding out by hand.)
macro_rules! gap_after {
    ($ty:ty, $after:ident : $after_size:ty => $next:ident, $bytes:literal) => {
        assert_eq!(
            offset_of!($ty, $next).saturating_sub(offset_of!($ty, $after) + size_of::<$after_size>()),
            $bytes,
            concat!(stringify!($ty), ": ", stringify!($bytes), " byte(s) between ", stringify!($after), " and ", stringify!($next))
        )
    };
    ($ty:ty, $after:ident : $after_size:ty => end of struct, $bytes:literal) => {
        assert_eq!(
            size_of::<$ty>().saturating_sub(offset_of!($ty, $after) + size_of::<$after_size>()),
            $bytes,
            concat!(stringify!($ty), ": ", stringify!($bytes), " byte(s) after ", stringify!($after), " to the end")
        )
    };
}

/// Every byte of the record that is *not* a field: its size minus the sizes of all its fields, the
/// header's field widths listed in the header's order.
///
/// This is the only place the padding is stated as a whole number (9, 2 and 0 bytes for the three
/// records). It fails when the record's size moves for any reason, which `size_of` alone would also
/// catch; it cannot see a field invented inside a gap, because the list is a transcription of the
/// header and not of the struct. It exists so the totals are written down where they can be checked
/// against the C measurement, which prints the same sum as the sum of its gaps.
macro_rules! padding_total {
    ($ty:ty, $bytes:literal, [$($field:ty),+ $(,)?]) => {
        assert_eq!(
            size_of::<$ty>().saturating_sub(0 $(+ size_of::<$field>())+),
            $bytes,
            concat!(stringify!($ty), ": ", stringify!($bytes), " byte(s) of compiler padding in all")
        )
    };
}

#[test]
fn compiler_padding_matches_the_header() {
    // VAEncSequenceParameterBufferHEVC: four holes, 9 bytes, none of which shows in its 116.
    gap_after!(VAEncSequenceParameterBufferHEVC, general_tier_flag: u8 => intra_period, 1);
    gap_after!(VAEncSequenceParameterBufferHEVC, max_transform_hierarchy_depth_intra: u8 => pcm_sample_bit_depth_luma_minus1, 2);
    gap_after!(VAEncSequenceParameterBufferHEVC, vui_parameters_present_flag: u8 => vui_fields, 3);
    gap_after!(VAEncSequenceParameterBufferHEVC, aspect_ratio_idc: u8 => sar_width, 3);
    gap_after!(VAEncSequenceParameterBufferHEVC, va_reserved: [u32; VA_PADDING_MEDIUM - 1] => end of struct, 0);
    padding_total!(
        VAEncSequenceParameterBufferHEVC,
        9,
        [
            u8,
            u8,
            u8,
            u32,
            u32,
            u32,
            u32,
            u16,
            u16,
            u32,
            u8,
            u8,
            u8,
            u8,
            u8,
            u8,
            u32,
            u32,
            u32,
            u32,
            u8,
            u32,
            u8,
            u32,
            u32,
            u32,
            u32,
            u16,
            u8,
            u8,
            u32,
            [u32; VA_PADDING_MEDIUM - 1],
        ]
    );

    // VAEncPictureParameterBufferHEVC: one hole, 2 bytes, before the 32-bit `pic_fields`.
    gap_after!(VAEncPictureParameterBufferHEVC, nal_unit_type: u8 => pic_fields, 2);
    gap_after!(VAEncPictureParameterBufferHEVC, va_byte_reserved: u8 => scc_fields, 0);
    gap_after!(VAEncPictureParameterBufferHEVC, scc_fields: u16 => va_reserved, 0);
    gap_after!(VAEncPictureParameterBufferHEVC, va_reserved: [u32; VA_PADDING_HIGH - 1] => end of struct, 0);
    padding_total!(
        VAEncPictureParameterBufferHEVC,
        2,
        [
            VAPictureHEVC,
            [VAPictureHEVC; 15],
            VABufferID,
            u8,
            u8,
            u8,
            u8,
            i8,
            i8,
            u8,
            u8,
            [u8; 19],
            [u8; 21],
            u8,
            u8,
            u8,
            u8,
            u8,
            u8,
            u32,
            u8,
            u8,
            u16,
            [u32; VA_PADDING_HIGH - 1],
        ]
    );

    // VAEncSliceParameterBufferHEVC: no hole at all, every field starting where the last one ended.
    gap_after!(VAEncSliceParameterBufferHEVC, slice_tc_offset_div2: i8 => slice_fields, 0);
    gap_after!(VAEncSliceParameterBufferHEVC, slice_fields: u32 => pred_weight_table_bit_offset, 0);
    gap_after!(VAEncSliceParameterBufferHEVC, pred_weight_table_bit_length: u32 => va_reserved, 0);
    gap_after!(VAEncSliceParameterBufferHEVC, va_reserved: [u32; VA_PADDING_MEDIUM - 2] => end of struct, 0);
    padding_total!(
        VAEncSliceParameterBufferHEVC,
        0,
        [
            u32,
            u32,
            u8,
            u8,
            u8,
            u8,
            [VAPictureHEVC; 15],
            [VAPictureHEVC; 15],
            u8,
            i8,
            [i8; 15],
            [i8; 15],
            [[i8; 2]; 15],
            [[i8; 2]; 15],
            [i8; 15],
            [i8; 15],
            [[i8; 2]; 15],
            [[i8; 2]; 15],
            u8,
            i8,
            i8,
            i8,
            i8,
            i8,
            u32,
            u32,
            u32,
            [u32; VA_PADDING_MEDIUM - 2],
        ]
    );
}

